import tailwindcss from '@tailwindcss/vite';
import { defineConfig } from 'wxt';

import packageJson from './package.json' with { type: 'json' };

// Manifest is generated by WXT from this file plus the entrypoints.
// Hard Rule 8: permissions are minimal and justified in Decisions.md.
// Hard Rule 9: CSP is strict; no remote code, no inline scripts, no eval.
// Sprint 0: host_permissions is deliberately empty (observers arrive in Sprint 2).
export default defineConfig({
  // Explicit imports everywhere; no magic globals in reviewed code.
  imports: false,
  manifestVersion: 3,
  manifest: {
    name: 'Attest',
    description: packageJson.description,
    minimum_chrome_version: '120',
    permissions: ['storage', 'alarms'],
    host_permissions: [],
    content_security_policy: {
      extension_pages: "script-src 'self'; object-src 'none'",
    },
    action: {
      default_title: 'Attest: receipts for your AI agents',
    },
  },
  zip: {
    artifactTemplate: '{{name}}-{{version}}.zip',
  },
  vite: () => ({
    plugins: [tailwindcss()],
    oxc: {
      jsx: { runtime: 'automatic', importSource: 'preact' },
    },
    build: {
      // Readable output for store review (no obfuscation); source maps kept for CI artifacts.
      sourcemap: true,
    },
  }),
});
